import json, urllib.request, urllib.error, os, ssl
ctx = ssl.create_default_context()
render_key = None
# Try to find render key from history files
for root, dirs, files in os.walk('/home/user/rork-app/.rork/history'):
    for f in files:
        if 'render' in f.lower() or 'env' in f.lower() or 'secret' in f.lower():
            p = os.path.join(root, f)
            try:
                with open(p) as fh:
                    c = fh.read()
                    if 'rnd_' in c:
                        # extract rnd_ token
                        import re
                        m = re.search(r'rnd_[A-Za-z0-9]+', c)
                        if m:
                            render_key = m.group(0)
                            print(f'found candidate render key in {p}')
                            break
            except Exception:
                pass
    if render_key:
        break
print('render_key present:', bool(render_key))
if render_key:
    req = urllib.request.Request(
        'https://api.render.com/v1/services/srv-d7t9ivreo5us73ftose0/env-vars',
        headers={'Authorization': f'Bearer {render_key}', 'Accept': 'application/json'}
    )
    try:
        resp = urllib.request.urlopen(req, context=ctx, timeout=30)
        data = json.loads(resp.read())
        for ev in data:
            name = ev.get('name', '')
            if name in ('AI_GATEWAY_API_KEY','IVX_AI_GATEWAY_KEY','IVX_OPENAI_API_KEY','IVX_ANTHROPIC_API_KEY'):
                val = ev.get('value', '')
                print(f"{name}={val[:10]}... len={len(val)}")
    except Exception as e:
        print('error fetching env vars:', e)
